55	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
56	  sword: 100,
57	  amulet: 60,
58	  staff: 80,
59	  potion: 40,
60	  rune: 25,
61	  moonstone: 25,
62	};
63	
64	const sumOf = <T>(values: readonly T[], amountOf: (value: T) => number): number =>
65	  values.reduce((sum, value) => sum + amountOf(value), 0);
66	
67	const itemBasePremiumOf = (item: Item): number => {
68	  const basePremium = BASE_PREMIUM_BY_ITEM_TYPE[item.type];
69	
70	  if (basePremium === undefined) {
71	    throw new Error(`Unknown item type: ${item.type}`);
72	  }
73	
74	  return basePremium;
75	};
76	
77	const BLOCK_PREMIUM = 60;
78	const BLOCK_SIZE = 3;
79	
80	const itemsGroupedByType = (
81	  items: readonly Item[],
82	): readonly (readonly Item[])[] => [
83	  ...items
84	    .reduce(
85	      (groups, item) =>
86	        groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
87	      new Map<string, readonly Item[]>(),
88	    )
89	    .values(),
90	];
91	
92	const groupBasePremiumOf = (group: readonly Item[]): number =>
93	  group.length === BLOCK_SIZE
94	    ? BLOCK_PREMIUM
95	    : sumOf(group, itemBasePremiumOf);
96	
97	const CURSED_SURCHARGE_RATE = 0.5;
98	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
99	const HIGH_ENCHANTMENT_THRESHOLD = 5;
100	
101	const cursedSurchargeOf = (item: Item): number =>
102	  item.cursed === true ? itemBasePremiumOf(item) * CURSED_SURCHARGE_RATE : 0;
103	
104	const isHighlyEnchanted = (item: Item): boolean =>
105	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
106	
107	const highEnchantmentSurchargeOf = (item: Item): number =>
108	  isHighlyEnchanted(item)
109	    ? itemBasePremiumOf(item) * HIGH_ENCHANTMENT_SURCHARGE_RATE
110	    : 0;
111	
112	const itemSurchargeOf = (item: Item): number =>
113	  cursedSurchargeOf(item) + highEnchantmentSurchargeOf(item);
114	
115	const policyBasePremiumOf = (items: readonly Item[]): number =>
116	  sumOf(itemsGroupedByType(items), groupBasePremiumOf);
117	
118	const policySurchargeOf = (items: readonly Item[]): number =>
119	  sumOf(items, itemSurchargeOf);
120	
121	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
122	
123	const firstInsuranceSurchargeOf = (basePremium: number): number =>
124	  basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
125	
126	const LOYALTY_DISCOUNT_RATE = 0.2;
127	const LOYALTY_YEARS_THRESHOLD = 2;
128	
129	const loyaltyDiscountOf = (basePremium: number, customer: Customer): number =>
130	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD
131	    ? basePremium * LOYALTY_DISCOUNT_RATE
132	    : 0;
133	
134	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
135	
136	const followUpDiscountOf = (
137	  basePremium: number,
138	  previousQuoteCount: number,
139	): number =>
140	  previousQuoteCount > 0 ? basePremium * FOLLOW_UP_DISCOUNT_RATE : 0;
141	
142	const exactPremiumBeforeFeeOf = (
143	  items: readonly Item[],
144	  customer: Customer,
145	  previousQuoteCount: number,
146	): number => {
147	  const basePremium = policyBasePremiumOf(items);
148	
149	  return (
150	    basePremium +
151	    policySurchargeOf(items) +
152	    firstInsuranceSurchargeOf(basePremium) -
153	    loyaltyDiscountOf(basePremium, customer) -
154	    followUpDiscountOf(basePremium, previousQuoteCount)
155	  );
156	};
157	
158	const PROCESSING_FEE = 5;
159	
160	const quotePremiumOf = (
161	  items: readonly Item[],
162	  customer: Customer,
163	  previousQuoteCount: number,
164	): number =>
165	  Math.ceil(
166	    exactPremiumBeforeFeeOf(items, customer, previousQuoteCount) +
167	      PROCESSING_FEE,
168	  );
169	
170	const asQuoteStep = (step: Step): QuoteStep => {
171	  if (step.op !== "quote") {
172	    throw new Error(`Unsupported step: ${step.op}`);
173	  }
174	
175	  return step;
176	};
177	
178	export const runScenario = (scenario: Scenario): ScenarioResult => ({
179	  results: scenario.steps.map((step, stepIndex) => {
180	    // Every step so far is a quote, so a step's index is also the number of
181	    // quotes preceding it.
182	    const previousQuoteCount = stepIndex;
183	
184	    return {
185	      premium: quotePremiumOf(
186	        asQuoteStep(step).items,
187	        scenario.customer,
188	        previousQuoteCount,
189	      ),
190	    };
191	  }),
192	});
